INSERT INTO nb_card_text
(card_id,audience_code,language_code,content_version,title,subtitle,reflection_keywords,
 what_do_you_see,card_room,helpful_side,difficult_side,context_questions_json,
 own_card_language,possible_next_step,status_code)
VALUES
('wands-ace','ADULT','de','0.1.0','Ass der Stäbe',NULL,'Energie · Kreativität · Wille · Impuls · Potenzial · Anfang','Welcher neue Impuls zeigt sich hier? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Etwas möchte beginnen, ohne schon vollständig ausgearbeitet sein zu müssen. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Ein Anfang kann Energie freisetzen und einen neuen Möglichkeitsraum öffnen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Ein neuer Impuls muss nicht sofort umgesetzt werden. Zu viel Erwartung kann aus Neugier schnell Druck machen. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was möchte gerade entstehen?", "Welche Möglichkeit zieht deine Aufmerksamkeit an?", "Was braucht dieser Anfang, damit er nicht zu groß wird?"]','Welche Bedeutung hat ein neuer Anfang für dich gerade?','Du könntest den Impuls erst einmal benennen, ohne daraus schon ein Projekt zu machen.','draft-review'),
('wands-02','ADULT','de','0.1.0','Zwei der Stäbe',NULL,'Energie · Kreativität · Wille · Beziehung · Wahl · Balance','Welche zwei Kräfte möchten miteinander in Beziehung kommen? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Zwei Dinge stehen nebeneinander: Bedürfnisse, Möglichkeiten, Menschen oder Richtungen. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Du kannst Unterschiede wahrnehmen und prüfen, ob eine Verbindung oder bewusste Wahl möglich ist. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Balance bedeutet nicht, dass beide Seiten immer gleich viel Raum brauchen. Manchmal ist eine klare Priorität stimmiger. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Welche zwei Seiten stehen gerade nebeneinander?", "Müssen sie wirklich gegeneinander arbeiten?", "Welche Seite braucht heute mehr Raum?"]','Wie fühlt sich eine stimmige Wahl für dich an?','Du könntest beide Seiten einzeln benennen, bevor du entscheidest, wie sie zusammenpassen.','draft-review'),
('wands-03','ADULT','de','0.1.0','Drei der Stäbe',NULL,'Energie · Kreativität · Wille · Entwicklung · Austausch · erster Erfolg','Was beginnt durch Verbindung zu wachsen? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Etwas ist nicht mehr nur Idee. Durch Austausch, Zusammenarbeit oder erste Rückmeldung wird Entwicklung sichtbar. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Ein erster Erfolg kann zeigen, was trägt und wo weitere Möglichkeiten entstehen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Frühe Bewegung muss nicht bedeuten, dass alles schon sicher ist. Wachstum kann auch Korrektur und Umwege brauchen. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was funktioniert bereits?", "Wer oder was trägt zu dieser Entwicklung bei?", "Was möchtest du weiter beobachten, bevor du mehr investierst?"]','Was bedeutet Fortschritt für dich – unabhängig von Tempo?','Halte einen kleinen sichtbaren Fortschritt fest, bevor du sofort zum nächsten Schritt gehst.','draft-review'),
('wands-04','ADULT','de','0.1.0','Vier der Stäbe',NULL,'Energie · Kreativität · Wille · Stabilität · Schutz · Festhalten','Was gibt Halt – und wo wird Halt zum Festhalten? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Etwas hat Form bekommen und kann Schutz oder Orientierung geben. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Stabilität kann Sicherheit schaffen, Ressourcen bewahren und Erholung ermöglichen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Was einmal geschützt hat, kann später zu eng werden. Sicherheit und Beweglichkeit dürfen immer wieder neu austariert werden. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was gibt dir gerade Halt?", "Was möchtest du bewahren?", "Wo könnte mehr Beweglichkeit hilfreich sein?"]','Woran merkst du, dass Sicherheit dich trägt statt begrenzt?','Prüfe eine bestehende Struktur: schützt sie dich noch oder hält sie dich hauptsächlich fest?','draft-review'),
('wands-05','ADULT','de','0.1.0','Fünf der Stäbe',NULL,'Energie · Kreativität · Wille · Spannung · Veränderung · Herausforderung','Was gerät in Bewegung, weil etwas nicht mehr passt? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Unterschiede, Reibung oder Verlust von Gleichgewicht werden sichtbar. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Spannung kann Informationen liefern: Sie zeigt, wo Bedürfnisse, Grenzen oder Erwartungen nicht gut zusammenpassen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Konflikt muss nicht automatisch produktiv sein. Manchmal braucht es zuerst Schutz, Abstand oder Entlastung. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Wo genau entsteht Reibung?", "Was versucht die Spannung sichtbar zu machen?", "Braucht es Klärung, Veränderung oder zunächst Abstand?"]','Wie möchtest du mit Spannung umgehen, ohne dich selbst zu übergehen?','Benenne zuerst das Problem, ohne sofort eine vollständige Lösung finden zu müssen.','draft-review'),
('wands-06','ADULT','de','0.1.0','Sechs der Stäbe',NULL,'Energie · Kreativität · Wille · Übergang · Ausgleich · Unterstützung','Was wird leichter, wenn du Hilfe oder Bewegung zulässt? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Etwas beginnt sich neu zu sortieren. Unterstützung, Ausgleich oder ein Ortswechsel können den Übergang tragen. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Du musst Veränderung nicht allein bewältigen. Hilfe kann Ressourcen freisetzen und Bewegung ermöglichen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Unterstützung passt nur, wenn sie wirklich hilfreich ist. Nicht jede gut gemeinte Hilfe entspricht deinem Bedarf. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was wird gerade leichter?", "Welche Unterstützung wäre tatsächlich passend?", "Was möchtest du selbst bestimmen, auch wenn du Hilfe annimmst?"]','Wie sieht Unterstützung aus, die deine Selbstbestimmung erhält?','Du könntest eine konkrete Form von Hilfe benennen, die dir wirklich etwas abnimmt.','draft-review'),
('wands-07','ADULT','de','0.1.0','Sieben der Stäbe',NULL,'Energie · Kreativität · Wille · Prüfung · Haltung · mehrere Wege','Welcher Weg entspricht dir, wenn nicht alles gleichzeitig möglich ist? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Mehrere Möglichkeiten oder Anforderungen konkurrieren um Aufmerksamkeit. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Eine bewusste Haltung kann helfen, nicht jede Option gleichzeitig verfolgen oder verteidigen zu müssen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Entscheidungskraft kann in Überforderung kippen, wenn zu viele Möglichkeiten offen bleiben oder ständig begründet werden müssen. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Welche Möglichkeiten sind wirklich relevant?", "Was passt zu deinen Werten oder Bedürfnissen?", "Was darf bewusst nicht gewählt werden?"]','Was macht eine Entscheidung zu deiner Entscheidung?','Reduziere die Auswahl auf die zwei oder drei Optionen, die tatsächlich zu dir gehören.','draft-review'),
('wands-08','ADULT','de','0.1.0','Acht der Stäbe',NULL,'Energie · Kreativität · Wille · Vertiefung · Dynamik · Konzentration','Wohin fließt deine Energie gerade besonders stark? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Aufmerksamkeit verdichtet sich. Etwas gewinnt Tempo, Tiefe oder Fokus. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Konzentration kann Lernen, Bewegung und spürbaren Fortschritt ermöglichen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Starker Fokus kann andere Bedürfnisse unsichtbar machen. Intensität ist nicht automatisch ein Zeichen dafür, dass etwas weitergeführt werden sollte. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was zieht gerade besonders viel Aufmerksamkeit?", "Fühlt sich die Intensität nährend oder erschöpfend an?", "Was brauchst du, damit Fokus nicht auf Kosten von Grundbedürfnissen geht?"]','Wie fühlt sich guter Fokus in deinem Körper und Kopf an?','Setze einen bewussten Zwischenstopp, an dem du prüfst, ob der Fokus weiterhin gut tut.','draft-review'),
('wands-09','ADULT','de','0.1.0','Neun der Stäbe',NULL,'Energie · Kreativität · Wille · Reife · Eigenständigkeit · Schwelle','Was hast du bereits aufgebaut, das dich jetzt trägt? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Erfahrung ist sichtbar geworden. Du stehst an einer Schwelle und kannst auf bereits entwickelte Fähigkeiten oder Ressourcen zurückgreifen. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Eigenständigkeit kann Vertrauen stärken, weil du erkennst, was du bereits gelernt und aufgebaut hast. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Selbstständigkeit bedeutet nicht, alles allein machen zu müssen. Reife kann auch darin liegen, Grenzen und Unterstützungsbedarf zu kennen. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was trägt dich bereits?", "Welche Erfahrung hilft dir jetzt?", "Wo möchtest du selbst entscheiden – und wo Unterstützung nutzen?"]','Welche Form von Eigenständigkeit passt zu dir?','Erinnere dich an eine Fähigkeit oder Ressource, die dir schon einmal geholfen hat.','draft-review'),
('wands-10','ADULT','de','0.1.0','Zehn der Stäbe',NULL,'Energie · Kreativität · Wille · Fülle · Abschluss · nächste Ebene','Was ist voll geworden und möchte neu geordnet werden? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Ein Zyklus hat viel angesammelt: Erfahrungen, Aufgaben, Beziehungen oder Ressourcen. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Ein Abschluss kann sichtbar machen, was entstanden ist und was du mitnehmen möchtest. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Fülle kann auch Überlastung sein. Nicht alles, was aufgebaut wurde, muss dauerhaft weitergetragen werden. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was ist jetzt vollständig genug?", "Was möchtest du behalten?", "Was darf beendet, verteilt oder losgelassen werden?"]','Woran erkennst du, dass ein Abschnitt abgeschlossen sein darf?','Wähle eine Sache, die du bewusst abschließen oder aus deinem aktuellen Raum herausnehmen möchtest.','draft-review'),
('wands-page','ADULT','de','0.1.0','Bube der Stäbe',NULL,'Energie · Kreativität · Wille · Neugier · Botschaft · Erkundung','Was möchte mit neugierigem Blick entdeckt werden? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Der Bube steht für Lernen, Fragen und erste Begegnung mit einem Thema. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Neugier erlaubt, etwas zu erforschen, ohne schon kompetent oder sicher sein zu müssen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Nicht jede neue Information braucht sofort Aufmerksamkeit. Neugier darf Grenzen haben. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was möchtest du genauer verstehen?", "Welche Frage ist wirklich deine?", "Wie viel Neues ist gerade angenehm?"]','Wie lernst oder erkundest du am liebsten?','Formuliere eine einzige Frage, der du heute folgen möchtest.','draft-review'),
('wands-knight','ADULT','de','0.1.0','Ritter der Stäbe',NULL,'Energie · Kreativität · Wille · Bewegung · Streben · Ausdruck','Welche Energie will handeln – und welches Tempo passt? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Etwas will in Bewegung kommen und sichtbar werden. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Handlung kann Klarheit schaffen und einen inneren Impuls in Erfahrung übersetzen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Geschwindigkeit kann wichtige Signale überdecken. Nicht jeder starke Impuls braucht sofort eine große Handlung. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Was möchte in Bewegung kommen?", "Welches Tempo passt zu deinen Ressourcen?", "Was wäre eine kleinere Form derselben Bewegung?"]','Wie sieht Handeln aus, wenn Tempo nicht mit Mut verwechselt wird?','Wähle die kleinste Handlung, die den Impuls sichtbar macht, ohne dich zu überfordern.','draft-review'),
('wands-queen','ADULT','de','0.1.0','Königin der Stäbe',NULL,'Energie · Kreativität · Wille · innere Reife · Empfangen · Verkörperung','Wie kannst du diese Qualität von innen heraus leben? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Die Königin steht für eine Qualität, die nicht bewiesen werden muss. Sie wird wahrgenommen, gehalten und verkörpert. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Innere Reife kann bedeuten, Bedürfnisse, Grenzen und Fähigkeiten ernst zu nehmen, ohne sie ständig rechtfertigen zu müssen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Empfangen und Innehalten können schwierig sein, wenn Selbstwert stark an Leistung oder Fürsorge für andere gebunden ist. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Welche Qualität ist bereits in dir vorhanden?", "Was darfst du empfangen statt leisten?", "Wo möchtest du dir selbst mehr Glauben schenken?"]','Welche Stärke musst du niemandem beweisen?','Gib einer bereits vorhandenen Fähigkeit Raum, ohne sie heute noch verbessern zu müssen.','draft-review'),
('wands-king','ADULT','de','0.1.0','König der Stäbe',NULL,'Energie · Kreativität · Wille · Verantwortung · Führung · Gestaltung','Wie kannst du diese Kraft bewusst und verantwortlich führen? Was zeigt sich dabei in deiner Energie, Kreativität oder deinem Willen?','Der König steht für bewusst eingesetzte Gestaltungskraft und Verantwortung. Bei den Stäbe richtet sich der Blick dabei besonders auf deine Energie, deine Gestaltungskraft und deinen Willen.','Führung kann bedeuten, Entscheidungen transparent zu treffen, Ressourcen zu schützen und anderen Raum zu lassen. Hier darf besonders sichtbar werden, was dich belebt, motiviert oder schöpferisch in Bewegung bringt.','Verantwortung wird problematisch, wenn sie Kontrolle ersetzt oder wenn du mehr trägst, als tatsächlich zu dir gehört. Achte darauf, ob Begeisterung in Überforderung, Druck oder zu viel gleichzeitige Aktivität kippt.','["Wofür bist du wirklich verantwortlich?", "Was kannst du gestalten – und was nicht?", "Wie kann deine Entscheidung auch Grenzen und andere Perspektiven berücksichtigen?"]','Was bedeutet verantwortliche Gestaltung für dich?','Trenne eine Verantwortung, die wirklich bei dir liegt, von einer, die du nicht übernehmen musst.','draft-review'),
('swords-ace','ADULT','de','0.1.0','Ass der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Impuls · Potenzial · Anfang','Welcher neue Impuls zeigt sich hier? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Etwas möchte beginnen, ohne schon vollständig ausgearbeitet sein zu müssen. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Ein Anfang kann Energie freisetzen und einen neuen Möglichkeitsraum öffnen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Ein neuer Impuls muss nicht sofort umgesetzt werden. Zu viel Erwartung kann aus Neugier schnell Druck machen. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was möchte gerade entstehen?", "Welche Möglichkeit zieht deine Aufmerksamkeit an?", "Was braucht dieser Anfang, damit er nicht zu groß wird?"]','Welche Bedeutung hat ein neuer Anfang für dich gerade?','Du könntest den Impuls erst einmal benennen, ohne daraus schon ein Projekt zu machen.','draft-review'),
('swords-02','ADULT','de','0.1.0','Zwei der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Beziehung · Wahl · Balance','Welche zwei Kräfte möchten miteinander in Beziehung kommen? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Zwei Dinge stehen nebeneinander: Bedürfnisse, Möglichkeiten, Menschen oder Richtungen. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Du kannst Unterschiede wahrnehmen und prüfen, ob eine Verbindung oder bewusste Wahl möglich ist. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Balance bedeutet nicht, dass beide Seiten immer gleich viel Raum brauchen. Manchmal ist eine klare Priorität stimmiger. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Welche zwei Seiten stehen gerade nebeneinander?", "Müssen sie wirklich gegeneinander arbeiten?", "Welche Seite braucht heute mehr Raum?"]','Wie fühlt sich eine stimmige Wahl für dich an?','Du könntest beide Seiten einzeln benennen, bevor du entscheidest, wie sie zusammenpassen.','draft-review'),
('swords-03','ADULT','de','0.1.0','Drei der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Entwicklung · Austausch · erster Erfolg','Was beginnt durch Verbindung zu wachsen? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Etwas ist nicht mehr nur Idee. Durch Austausch, Zusammenarbeit oder erste Rückmeldung wird Entwicklung sichtbar. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Ein erster Erfolg kann zeigen, was trägt und wo weitere Möglichkeiten entstehen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Frühe Bewegung muss nicht bedeuten, dass alles schon sicher ist. Wachstum kann auch Korrektur und Umwege brauchen. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was funktioniert bereits?", "Wer oder was trägt zu dieser Entwicklung bei?", "Was möchtest du weiter beobachten, bevor du mehr investierst?"]','Was bedeutet Fortschritt für dich – unabhängig von Tempo?','Halte einen kleinen sichtbaren Fortschritt fest, bevor du sofort zum nächsten Schritt gehst.','draft-review'),
('swords-04','ADULT','de','0.1.0','Vier der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Stabilität · Schutz · Festhalten','Was gibt Halt – und wo wird Halt zum Festhalten? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Etwas hat Form bekommen und kann Schutz oder Orientierung geben. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Stabilität kann Sicherheit schaffen, Ressourcen bewahren und Erholung ermöglichen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Was einmal geschützt hat, kann später zu eng werden. Sicherheit und Beweglichkeit dürfen immer wieder neu austariert werden. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was gibt dir gerade Halt?", "Was möchtest du bewahren?", "Wo könnte mehr Beweglichkeit hilfreich sein?"]','Woran merkst du, dass Sicherheit dich trägt statt begrenzt?','Prüfe eine bestehende Struktur: schützt sie dich noch oder hält sie dich hauptsächlich fest?','draft-review'),
('swords-05','ADULT','de','0.1.0','Fünf der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Spannung · Veränderung · Herausforderung','Was gerät in Bewegung, weil etwas nicht mehr passt? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Unterschiede, Reibung oder Verlust von Gleichgewicht werden sichtbar. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Spannung kann Informationen liefern: Sie zeigt, wo Bedürfnisse, Grenzen oder Erwartungen nicht gut zusammenpassen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Konflikt muss nicht automatisch produktiv sein. Manchmal braucht es zuerst Schutz, Abstand oder Entlastung. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Wo genau entsteht Reibung?", "Was versucht die Spannung sichtbar zu machen?", "Braucht es Klärung, Veränderung oder zunächst Abstand?"]','Wie möchtest du mit Spannung umgehen, ohne dich selbst zu übergehen?','Benenne zuerst das Problem, ohne sofort eine vollständige Lösung finden zu müssen.','draft-review'),
('swords-06','ADULT','de','0.1.0','Sechs der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Übergang · Ausgleich · Unterstützung','Was wird leichter, wenn du Hilfe oder Bewegung zulässt? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Etwas beginnt sich neu zu sortieren. Unterstützung, Ausgleich oder ein Ortswechsel können den Übergang tragen. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Du musst Veränderung nicht allein bewältigen. Hilfe kann Ressourcen freisetzen und Bewegung ermöglichen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Unterstützung passt nur, wenn sie wirklich hilfreich ist. Nicht jede gut gemeinte Hilfe entspricht deinem Bedarf. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was wird gerade leichter?", "Welche Unterstützung wäre tatsächlich passend?", "Was möchtest du selbst bestimmen, auch wenn du Hilfe annimmst?"]','Wie sieht Unterstützung aus, die deine Selbstbestimmung erhält?','Du könntest eine konkrete Form von Hilfe benennen, die dir wirklich etwas abnimmt.','draft-review'),
('swords-07','ADULT','de','0.1.0','Sieben der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Prüfung · Haltung · mehrere Wege','Welcher Weg entspricht dir, wenn nicht alles gleichzeitig möglich ist? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Mehrere Möglichkeiten oder Anforderungen konkurrieren um Aufmerksamkeit. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Eine bewusste Haltung kann helfen, nicht jede Option gleichzeitig verfolgen oder verteidigen zu müssen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Entscheidungskraft kann in Überforderung kippen, wenn zu viele Möglichkeiten offen bleiben oder ständig begründet werden müssen. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Welche Möglichkeiten sind wirklich relevant?", "Was passt zu deinen Werten oder Bedürfnissen?", "Was darf bewusst nicht gewählt werden?"]','Was macht eine Entscheidung zu deiner Entscheidung?','Reduziere die Auswahl auf die zwei oder drei Optionen, die tatsächlich zu dir gehören.','draft-review'),
('swords-08','ADULT','de','0.1.0','Acht der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Vertiefung · Dynamik · Konzentration','Wohin fließt deine Energie gerade besonders stark? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Aufmerksamkeit verdichtet sich. Etwas gewinnt Tempo, Tiefe oder Fokus. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Konzentration kann Lernen, Bewegung und spürbaren Fortschritt ermöglichen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Starker Fokus kann andere Bedürfnisse unsichtbar machen. Intensität ist nicht automatisch ein Zeichen dafür, dass etwas weitergeführt werden sollte. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was zieht gerade besonders viel Aufmerksamkeit?", "Fühlt sich die Intensität nährend oder erschöpfend an?", "Was brauchst du, damit Fokus nicht auf Kosten von Grundbedürfnissen geht?"]','Wie fühlt sich guter Fokus in deinem Körper und Kopf an?','Setze einen bewussten Zwischenstopp, an dem du prüfst, ob der Fokus weiterhin gut tut.','draft-review'),
('swords-09','ADULT','de','0.1.0','Neun der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Reife · Eigenständigkeit · Schwelle','Was hast du bereits aufgebaut, das dich jetzt trägt? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Erfahrung ist sichtbar geworden. Du stehst an einer Schwelle und kannst auf bereits entwickelte Fähigkeiten oder Ressourcen zurückgreifen. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Eigenständigkeit kann Vertrauen stärken, weil du erkennst, was du bereits gelernt und aufgebaut hast. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Selbstständigkeit bedeutet nicht, alles allein machen zu müssen. Reife kann auch darin liegen, Grenzen und Unterstützungsbedarf zu kennen. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was trägt dich bereits?", "Welche Erfahrung hilft dir jetzt?", "Wo möchtest du selbst entscheiden – und wo Unterstützung nutzen?"]','Welche Form von Eigenständigkeit passt zu dir?','Erinnere dich an eine Fähigkeit oder Ressource, die dir schon einmal geholfen hat.','draft-review'),
('swords-10','ADULT','de','0.1.0','Zehn der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Fülle · Abschluss · nächste Ebene','Was ist voll geworden und möchte neu geordnet werden? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Ein Zyklus hat viel angesammelt: Erfahrungen, Aufgaben, Beziehungen oder Ressourcen. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Ein Abschluss kann sichtbar machen, was entstanden ist und was du mitnehmen möchtest. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Fülle kann auch Überlastung sein. Nicht alles, was aufgebaut wurde, muss dauerhaft weitergetragen werden. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was ist jetzt vollständig genug?", "Was möchtest du behalten?", "Was darf beendet, verteilt oder losgelassen werden?"]','Woran erkennst du, dass ein Abschnitt abgeschlossen sein darf?','Wähle eine Sache, die du bewusst abschließen oder aus deinem aktuellen Raum herausnehmen möchtest.','draft-review'),
('swords-page','ADULT','de','0.1.0','Bube der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Neugier · Botschaft · Erkundung','Was möchte mit neugierigem Blick entdeckt werden? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Der Bube steht für Lernen, Fragen und erste Begegnung mit einem Thema. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Neugier erlaubt, etwas zu erforschen, ohne schon kompetent oder sicher sein zu müssen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Nicht jede neue Information braucht sofort Aufmerksamkeit. Neugier darf Grenzen haben. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was möchtest du genauer verstehen?", "Welche Frage ist wirklich deine?", "Wie viel Neues ist gerade angenehm?"]','Wie lernst oder erkundest du am liebsten?','Formuliere eine einzige Frage, der du heute folgen möchtest.','draft-review'),
('swords-knight','ADULT','de','0.1.0','Ritter der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Bewegung · Streben · Ausdruck','Welche Energie will handeln – und welches Tempo passt? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Etwas will in Bewegung kommen und sichtbar werden. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Handlung kann Klarheit schaffen und einen inneren Impuls in Erfahrung übersetzen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Geschwindigkeit kann wichtige Signale überdecken. Nicht jeder starke Impuls braucht sofort eine große Handlung. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Was möchte in Bewegung kommen?", "Welches Tempo passt zu deinen Ressourcen?", "Was wäre eine kleinere Form derselben Bewegung?"]','Wie sieht Handeln aus, wenn Tempo nicht mit Mut verwechselt wird?','Wähle die kleinste Handlung, die den Impuls sichtbar macht, ohne dich zu überfordern.','draft-review'),
('swords-queen','ADULT','de','0.1.0','Königin der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · innere Reife · Empfangen · Verkörperung','Wie kannst du diese Qualität von innen heraus leben? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Die Königin steht für eine Qualität, die nicht bewiesen werden muss. Sie wird wahrgenommen, gehalten und verkörpert. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Innere Reife kann bedeuten, Bedürfnisse, Grenzen und Fähigkeiten ernst zu nehmen, ohne sie ständig rechtfertigen zu müssen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Empfangen und Innehalten können schwierig sein, wenn Selbstwert stark an Leistung oder Fürsorge für andere gebunden ist. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Welche Qualität ist bereits in dir vorhanden?", "Was darfst du empfangen statt leisten?", "Wo möchtest du dir selbst mehr Glauben schenken?"]','Welche Stärke musst du niemandem beweisen?','Gib einer bereits vorhandenen Fähigkeit Raum, ohne sie heute noch verbessern zu müssen.','draft-review'),
('swords-king','ADULT','de','0.1.0','König der Schwerter',NULL,'Gedanken · Klarheit · Konflikt · Verantwortung · Führung · Gestaltung','Wie kannst du diese Kraft bewusst und verantwortlich führen? Was zeigt sich dabei in deinen Gedanken, deiner Klarheit oder in einem Konflikt?','Der König steht für bewusst eingesetzte Gestaltungskraft und Verantwortung. Bei den Schwerter richtet sich der Blick dabei besonders auf deine Gedanken, Klarheit und innere oder äußere Konflikte.','Führung kann bedeuten, Entscheidungen transparent zu treffen, Ressourcen zu schützen und anderen Raum zu lassen. Hier kann besonders sichtbar werden, welche Gedanken Klarheit schaffen und welche Unterscheidung hilfreich ist.','Verantwortung wird problematisch, wenn sie Kontrolle ersetzt oder wenn du mehr trägst, als tatsächlich zu dir gehört. Gedanken können sich festfahren oder Konflikte verschärfen; Abstand und zusätzliche Perspektiven dürfen Teil der Klärung sein.','["Wofür bist du wirklich verantwortlich?", "Was kannst du gestalten – und was nicht?", "Wie kann deine Entscheidung auch Grenzen und andere Perspektiven berücksichtigen?"]','Was bedeutet verantwortliche Gestaltung für dich?','Trenne eine Verantwortung, die wirklich bei dir liegt, von einer, die du nicht übernehmen musst.','draft-review'),
('cups-ace','ADULT','de','0.1.0','Ass der Kelche',NULL,'Gefühl · Beziehung · Intuition · Impuls · Potenzial · Anfang','Welcher neue Impuls zeigt sich hier? Was zeigt sich dabei in deinen Gefühlen, Beziehungen oder deiner Intuition?','Etwas möchte beginnen, ohne schon vollständig ausgearbeitet sein zu müssen. Bei den Kelche richtet sich der Blick dabei besonders auf deine Gefühle, Beziehungen und Intuition.','Ein Anfang kann Energie freisetzen und einen neuen Möglichkeitsraum öffnen. Hier kann besonders sichtbar werden, was emotional stimmig ist, Verbindung schafft oder intuitiv Bedeutung erhält.','Ein neuer Impuls muss nicht sofort umgesetzt werden. Zu viel Erwartung kann aus Neugier schnell Druck machen. Gefühle sind wichtige Informationen, aber sie müssen nicht allein entscheiden; Grenzen und Realität dürfen mit im Raum bleiben.','["Was möchte gerade entstehen?", "Welche Möglichkeit zieht deine Aufmerksamkeit an?", "Was braucht dieser Anfang, damit er nicht zu groß wird?"]','Welche Bedeutung hat ein neuer Anfang für dich gerade?','Du könntest den Impuls erst einmal benennen, ohne daraus schon ein Projekt zu machen.','draft-review'),
('cups-02','ADULT','de','0.1.0','Zwei der Kelche',NULL,'Gefühl · Beziehung · Intuition · Beziehung · Wahl · Balance','Welche zwei Kräfte möchten miteinander in Beziehung kommen? Was zeigt sich dabei in deinen Gefühlen, Beziehungen oder deiner Intuition?','Zwei Dinge stehen nebeneinander: Bedürfnisse, Möglichkeiten, Menschen oder Richtungen. Bei den Kelche richtet sich der Blick dabei besonders auf deine Gefühle, Beziehungen und Intuition.','Du kannst Unterschiede wahrnehmen und prüfen, ob eine Verbindung oder bewusste Wahl möglich ist. Hier kann besonders sichtbar werden, was emotional stimmig ist, Verbindung schafft oder intuitiv Bedeutung erhält.','Balance bedeutet nicht, dass beide Seiten immer gleich viel Raum brauchen. Manchmal ist eine klare Priorität stimmiger. Gefühle sind wichtige Informationen, aber sie müssen nicht allein entscheiden; Grenzen und Realität dürfen mit im Raum bleiben.','["Welche zwei Seiten stehen gerade nebeneinander?", "Müssen sie wirklich gegeneinander arbeiten?", "Welche Seite braucht heute mehr Raum?"]','Wie fühlt sich eine stimmige Wahl für dich an?','Du könntest beide Seiten einzeln benennen, bevor du entscheidest, wie sie zusammenpassen.','draft-review'),
('cups-03','ADULT','de','0.1.0','Drei der Kelche',NULL,'Gefühl · Beziehung · Intuition · Entwicklung · Austausch · erster Erfolg','Was beginnt durch Verbindung zu wachsen? Was zeigt sich dabei in deinen Gefühlen, Beziehungen oder deiner Intuition?','Etwas ist nicht mehr nur Idee. Durch Austausch, Zusammenarbeit oder erste Rückmeldung wird Entwicklung sichtbar. Bei den Kelche richtet sich der Blick dabei besonders auf deine Gefühle, Beziehungen und Intuition.','Ein erster Erfolg kann zeigen, was trägt und wo weitere Möglichkeiten entstehen. Hier kann besonders sichtbar werden, was emotional stimmig ist, Verbindung schafft oder intuitiv Bedeutung erhält.','Frühe Bewegung muss nicht bedeuten, dass alles schon sicher ist. Wachstum kann auch Korrektur und Umwege brauchen. Gefühle sind wichtige Informationen, aber sie müssen nicht allein entscheiden; Grenzen und Realität dürfen mit im Raum bleiben.','["Was funktioniert bereits?", "Wer oder was trägt zu dieser Entwicklung bei?", "Was möchtest du weiter beobachten, bevor du mehr investierst?"]','Was bedeutet Fortschritt für dich – unabhängig von Tempo?','Halte einen kleinen sichtbaren Fortschritt fest, bevor du sofort zum nächsten Schritt gehst.','draft-review'),
('cups-04','ADULT','de','0.1.0','Vier der Kelche',NULL,'Gefühl · Beziehung · Intuition · Stabilität · Schutz · Festhalten','Was gibt Halt – und wo wird Halt zum Festhalten? Was zeigt sich dabei in deinen Gefühlen, Beziehungen oder deiner Intuition?','Etwas hat Form bekommen und kann Schutz oder Orientierung geben. Bei den Kelche richtet sich der Blick dabei besonders auf deine Gefühle, Beziehungen und Intuition.','Stabilität kann Sicherheit schaffen, Ressourcen bewahren und Erholung ermöglichen. Hier kann besonders sichtbar werden, was emotional stimmig ist, Verbindung schafft oder intuitiv Bedeutung erhält.','Was einmal geschützt hat, kann später zu eng werden. Sicherheit und Beweglichkeit dürfen immer wieder neu austariert werden. Gefühle sind wichtige Informationen, aber sie müssen nicht allein entscheiden; Grenzen und Realität dürfen mit im Raum bleiben.','["Was gibt dir gerade Halt?", "Was möchtest du bewahren?", "Wo könnte mehr Beweglichkeit hilfreich sein?"]','Woran merkst du, dass Sicherheit dich trägt statt begrenzt?','Prüfe eine bestehende Struktur: schützt sie dich noch oder hält sie dich hauptsächlich fest?','draft-review'),
